import React, { useState } from 'react';
import axios from 'axios';

function App(){
  const [message, setMessage] = useState('');
  const [chat, setChat] = useState([]);
  const [loading, setLoading] = useState(false);

  async function sendMessage(e){
    e.preventDefault();
    if(!message) return;
    const userMsg = { sender: 'You', text: message };
    setChat(c => [...c, userMsg]);
    setMessage('');
    setLoading(true);
    try{
     const res = await axios.post('http://localhost:5000/api/chat', { message, history: chat });

      setChat(c => [...c, { sender: 'Bot', text: res.data.reply }]);
    } catch (err){
      setChat(c => [...c, { sender: 'Bot', text: 'Error: could not reach backend' }]);
    } finally {
      setLoading(false);
    }
  }

  return (
    <div style={{maxWidth:700, margin:'2rem auto', fontFamily:'sans-serif'}}>
      <h2>AI Chatbot Demo</h2>
      <div style={{border:'1px solid #ddd', padding:10, minHeight:200}}>
        {chat.length === 0 && <p style={{color:'#666'}}>No messages yet. Say hi!</p>}
        {chat.map((m,i) => (
          <div key={i} style={{margin:'8px 0'}}>
            <strong>{m.sender}:</strong> <span>{m.text}</span>
          </div>
        ))}
        {loading && <p>Thinking...</p>}
      </div>
      <form onSubmit={sendMessage} style={{marginTop:10, display:'flex', gap:8}}>
        <input value={message} onChange={e=>setMessage(e.target.value)} placeholder="Type a message" style={{flex:1, padding:8}} />
        <button type="submit" style={{padding:'8px 12px'}}>Send</button>
      </form>
    </div>
  );
}

export default App;
